// Builds the print HTML from data/cards.json + config/print-settings.json:
//   build/home_print.html        — A4 sheets (instructions, alignment test, fronts/backs)
//   build/print_shop.html        — one card side per page with bleed + crop marks
//   build/layout-plan.json       — home-print sheet/slot plan used by QC (duplex mapping)
//   build/print-shop-plan.json   — page → card/side/gate map used by QC and the spec sheet
//   data/cards.csv               — flat export
// The web preview and editor (preview/, editor/) are generated by scripts/build-web.mjs.
import { loadProject, writeOut } from "./lib.mjs";
import { ROOT } from "./lib.mjs";
import { esc, head, renderFront, renderBack, loadBacks, cardGeometry } from "../src/templates.mjs";
import { cardsToCsv } from "../src/data-io.mjs";

const { settings, data, gateMap } = loadProject();
const G = cardGeometry(settings);
const backs = loadBacks(ROOT, data.gates);
const cards = data.cards;
const f2 = (n) => +n.toFixed(3);

/* ------------------------------------------------------------------ CSV */
writeOut("data/cards.csv", cardsToCsv(data));

const counts = {
  questions: cards.filter((c) => c.card_type === "question").length,
  answers: cards.filter((c) => c.card_type === "answer").length,
};

// Small vector glyphs for the print guide pages (system fonts are never used for ▲ / →).
const upTriangle = (x, y, s) => `<path d="M${f2(x)} ${f2(y - s)}L${f2(x + s * 0.9)} ${f2(y + s * 0.55)}H${f2(x - s * 0.9)}Z" class="t-tri"/>`;
const inlineTriangle = `<svg class="tri" viewBox="0 0 10 9" aria-hidden="true"><path d="M5 0.5L9.5 8.5H0.5Z" fill="currentColor"/></svg>`;

/* ---------------------------------------------------------- Home A4 print */
const hp = settings.home_print;
const cellW = hp.include_bleed ? G.cardW : G.trimW;
const cellH = hp.include_bleed ? G.cardH : G.trimH;
const blockW = hp.columns * cellW + (hp.columns - 1) * hp.gutter_mm;
const blockH = hp.rows * cellH + (hp.rows - 1) * hp.gutter_mm;
const marginX = (hp.paper_width_mm - blockW) / 2;
const marginY = (hp.paper_height_mm - blockH) / 2;
const perSheet = hp.columns * hp.rows;
if (marginX < 0 || marginY < 0) throw new Error(`Home print grid (${blockW}×${blockH} mm) does not fit on the paper.`);

const slotXY = (col, row) => ({ x: marginX + col * (cellW + hp.gutter_mm), y: marginY + row * (cellH + hp.gutter_mm) });
/** Where the back of front-slot (col,row) must be printed on the back page, seen from the back side. */
function backSlot(col, row) {
  if (hp.duplex_flip === "long-edge") return { col: hp.columns - 1 - col, row };
  if (hp.duplex_flip === "short-edge") return { col, row: hp.rows - 1 - row };
  throw new Error(`Unknown duplex_flip "${hp.duplex_flip}" (use long-edge or short-edge).`);
}

// Gate-pure packing: questions then answers of one gate, chunked into sheets.
const sheets = [];
for (const g of data.gates) {
  const gc = cards.filter((c) => c.gate === g.gate);
  for (let i = 0; i < gc.length; i += perSheet) sheets.push({ gate: g.gate, cards: gc.slice(i, i + perSheet) });
}

function cardInSlot(inner, x, y) {
  if (hp.include_bleed) return `<div class="slot" style="left:${f2(x)}mm;top:${f2(y)}mm">${inner}</div>`;
  return `<div class="slot clip" style="left:${f2(x)}mm;top:${f2(y)}mm;width:${G.trimW}mm;height:${G.trimH}mm"><div style="position:absolute;left:-${G.bleed}mm;top:-${G.bleed}mm">${inner}</div></div>`;
}

function cropMarksSvg(color) {
  const off = hp.crop_mark_offset_mm, len = hp.crop_mark_length_mm, sw = hp.crop_mark_stroke_mm;
  const inset = hp.include_bleed ? G.bleed : 0;
  const xs = new Set(), ys = new Set();
  for (let c = 0; c < hp.columns; c++) { const { x } = slotXY(c, 0); xs.add(f2(x + inset)); xs.add(f2(x + inset + G.trimW)); }
  for (let r = 0; r < hp.rows; r++) { const { y } = slotXY(0, r); ys.add(f2(y + inset)); ys.add(f2(y + inset + G.trimH)); }
  const L = [];
  for (const x of xs) {
    L.push([x, marginY - off - len, x, marginY - off]);
    L.push([x, marginY + blockH + off, x, marginY + blockH + off + len]);
  }
  for (const y of ys) {
    L.push([marginX - off - len, y, marginX - off, y]);
    L.push([marginX + blockW + off, y, marginX + blockW + off + len, y]);
  }
  return `<svg class="overlay" viewBox="0 0 ${hp.paper_width_mm} ${hp.paper_height_mm}" aria-hidden="true">${L.map(([a, b, c, d]) => `<line x1="${f2(a)}" y1="${f2(b)}" x2="${f2(c)}" y2="${f2(d)}" stroke="${color}" stroke-width="${sw}"/>`).join("")}</svg>`;
}

const sideLabel = (text) => `<div class="side-label" style="left:${f2(Math.max(2, marginX / 2 - 1.5))}mm">${esc(text)}</div>`;

const homePages = [];
const plan = { duplex_flip: hp.duplex_flip, packing: hp.packing, columns: hp.columns, rows: hp.rows, page_width_mm: hp.paper_width_mm, page_height_mm: hp.paper_height_mm, sheets: [] };
const totalSheets = sheets.length;
const firstCardPage = (hp.include_instructions ? 2 : 0) + (hp.include_alignment_test ? 2 : 0) + 1;
const testFrontPage = (hp.include_instructions ? 2 : 0) + 1;

// Instructions (2 pages = 1 duplex sheet)
if (hp.include_instructions) {
  const sheetRows = sheets.map((s, i) => {
    const q = s.cards.filter((c) => c.card_type === "question").map((c) => c.id);
    const a = s.cards.filter((c) => c.card_type === "answer").map((c) => c.id);
    const span = (ids, label) => (ids.length ? `${label} ${ids[0]}–${ids[ids.length - 1]}` : "");
    const p = firstCardPage + i * 2;
    return `<tr><td>${i + 1}</td><td>${p}–${p + 1}</td><td>Gate ${s.gate}</td><td>${[span(q, "Q"), span(a, "A")].filter(Boolean).join(" · ")}</td><td>${s.cards.length}</td></tr>`;
  }).join("");
  const lastPage = firstCardPage + totalSheets * 2 - 1;
  const flipEn = hp.duplex_flip === "long-edge" ? "Flip on long edge" : "Flip on short edge";
  const flipFr = hp.duplex_flip === "long-edge" ? "Retourner sur le bord long" : "Retourner sur le bord court";
  homePages.push(`<section class="page doc">
  <div class="doc-band"><span>INTERNATIONAL FAIR · AIRPORT GATES</span><span>PRINT GUIDE · GUIDE D'IMPRESSION</span></div>
  <h1>How to print this deck</h1><p class="fr-sub">Comment imprimer ce jeu de cartes</p>
  <p>This file prints all <b>${cards.length} cards</b> (${counts.questions} question cards + ${counts.answers} answer cards) on <b>${totalSheets} A4 sheets</b>, printed on both sides. Each sheet holds up to ${perSheet} cards of <b>one gate only</b>, so every back on a sheet is the same design.</p>
  <h2>1 · Printer settings <span>Réglages de l'imprimante</span></h2>
  <ul>
    <li><b>Paper:</b> A4, portrait. Card stock 200–300 g/m² if your printer accepts it (otherwise the heaviest paper it supports).</li>
    <li><b>Scale: 100 % / “Actual size”.</b> Turn OFF “Fit to page” / “Shrink to fit” — otherwise cards will be the wrong size and backs will not line up.</li>
    <li><b>Two-sided (duplex): ON — “${flipEn}”</b> (« ${flipFr} »). This file is laid out for <b>${hp.duplex_flip}</b> flipping.</li>
    <li><b>Colour</b>, best quality. Margins: none / borderless not required.</li>
  </ul>
  <h2>2 · Test first <span>Testez d'abord</span></h2>
  <ol>
    <li>Print <b>pages ${hp.include_alignment_test ? `${testFrontPage}–${testFrontPage + 1}` : "—"} only</b> (the alignment test) on one sheet, two-sided.</li>
    <li>Hold the sheet up to a window or lamp. Each cross on the back should sit exactly behind the cross on the front. The small ruler on the back shows the shift in millimetres.</li>
    <li>Check the <b>${inlineTriangle} TOP</b> arrows: if the back arrow points the same way as the front arrow, your flip setting matches. If it is upside down, switch between long-edge and short-edge flip and test again.</li>
    <li>A shift of 1 mm or less is normal and is absorbed by the ${G.bleed} mm bleed. Larger shifts: set <code>back_offset_x_mm</code> / <code>back_offset_y_mm</code> in <code>config/print-settings.json</code> and rebuild (see README).</li>
  </ol>
  <h2>3 · Print the cards <span>Imprimez les cartes</span></h2>
  <p>Print <b>pages ${firstCardPage}–${lastPage}</b> two-sided with the same settings. Odd pages are fronts, even pages are the matching backs.</p>
  <h2>4 · Cut <span>Découpez</span></h2>
  <p>Use a metal ruler and craft knife, or a guillotine. Line up with the short <b>crop marks</b> in the margins of the <b>front</b> side and cut right across the sheet. ${hp.include_bleed ? `Each card carries ${G.bleed} mm of extra artwork (bleed), so between two cards there are <b>two cut lines ${2 * G.bleed} mm apart</b> — the thin strip in between is waste.` : ""} Finished size: <b>${G.trimW} × ${G.trimH} mm</b>.</p>
  <p class="foot">Tip · Astuce : answer cards have a <b>yellow header</b> — sort them into a separate pile for the game host. Les cartes réponse ont un bandeau jaune.</p>
</section>`);
  homePages.push(`<section class="page doc">
  <div class="doc-band"><span>INTERNATIONAL FAIR · AIRPORT GATES</span><span>PRINT GUIDE · 2/2</span></div>
  <h2>No duplex printer? <span>Pas d'impression recto verso ?</span></h2>
  <ol>
    <li>Print the <b>odd pages</b> only (fronts) from page ${firstCardPage}.</li>
    <li>Put the printed stack back in the tray so the next print lands on the blank side, keeping the same order and top edge (test with one marked sheet first — every printer feeds differently).</li>
    <li>Print the <b>even pages</b> only (backs).</li>
  </ol>
  <p>Because every sheet contains a single gate, a back can never end up on another gate's front — the only thing to keep is the <b>sheet order</b>.</p>
  <h2>Sheet map <span>Plan des feuilles</span></h2>
  <table><thead><tr><th>Sheet</th><th>Pages</th><th>Gate</th><th>Cards (Q = question, A = answer)</th><th>#</th></tr></thead><tbody>${sheetRows}</tbody></table>
  ${hp.fill_all_back_slots ? `<p class="foot">Backs are printed in all ${perSheet} positions, even where a front position is empty (last sheet of each gate): this keeps the result correct whatever your printer's flip setting. Pieces with a blank front are spares — discard them, or write your own question on them.</p>` : ""}
</section>`);
}

// Alignment test (2 pages)
if (hp.include_alignment_test) {
  const front = [], back = [];
  const inset = hp.include_bleed ? G.bleed : 0;
  for (let i = 0; i < perSheet; i++) {
    const col = i % hp.columns, row = Math.floor(i / hp.columns);
    const { x, y } = slotXY(col, row);
    const cx = x + cellW / 2, cy = y + cellH / 2;
    front.push(`<rect x="${f2(x + inset)}" y="${f2(y + inset)}" width="${G.trimW}" height="${G.trimH}" rx="${G.radius}" class="t-trim"/>
      <line x1="${f2(cx - 8)}" y1="${f2(cy)}" x2="${f2(cx + 8)}" y2="${f2(cy)}" class="t-cross"/><line x1="${f2(cx)}" y1="${f2(cy - 8)}" x2="${f2(cx)}" y2="${f2(cy + 8)}" class="t-cross"/>
      <circle cx="${f2(cx)}" cy="${f2(cy)}" r="3" class="t-cross"/>
      ${upTriangle(cx - 4.2, y + inset + 7.9, 1.3)}<text x="${f2(cx + 1.2)}" y="${f2(y + inset + 9)}" class="t-lbl">TOP</text>
      <text x="${f2(cx)}" y="${f2(cy + 16)}" class="t-lbl">FRONT · SLOT ${i + 1}</text>`);
    const b = backSlot(col, row);
    const bp = slotXY(b.col, b.row);
    const bx = bp.x + cellW / 2 + hp.back_offset_x_mm, by = bp.y + cellH / 2 + hp.back_offset_y_mm;
    const ticks = [];
    for (let k = -4; k <= 4; k++) {
      if (k === 0) continue;
      const l = k % 2 === 0 ? 1.6 : 1;
      ticks.push(`<line x1="${f2(bx + k)}" y1="${f2(by - l)}" x2="${f2(bx + k)}" y2="${f2(by + l)}" class="t-tick"/><line x1="${f2(bx - l)}" y1="${f2(by + k)}" x2="${f2(bx + l)}" y2="${f2(by + k)}" class="t-tick"/>`);
    }
    const topY = bp.y + inset + 9 + hp.back_offset_y_mm;
    back.push(`<line x1="${f2(bx - 8)}" y1="${f2(by)}" x2="${f2(bx + 8)}" y2="${f2(by)}" class="t-cross b"/><line x1="${f2(bx)}" y1="${f2(by - 8)}" x2="${f2(bx)}" y2="${f2(by + 8)}" class="t-cross b"/>${ticks.join("")}
      ${upTriangle(bx - 4.2, topY - 1.1, 1.3)}<text x="${f2(bx + 1.2)}" y="${f2(topY)}" class="t-lbl">TOP</text>
      <text x="${f2(bx)}" y="${f2(by + 16)}" class="t-lbl">BACK OF SLOT ${i + 1}</text>
      <text x="${f2(bx)}" y="${f2(by + 20)}" class="t-small">1 tick = 1 mm</text>`);
  }
  const svg = (inner, label) => `<svg class="overlay" viewBox="0 0 ${hp.paper_width_mm} ${hp.paper_height_mm}">${inner.join("")}</svg>${sideLabel(label)}`;
  homePages.push(`<section class="page test">${svg(front, `ALIGNMENT TEST · FRONT (page ${testFrontPage}) · duplex: ${hp.duplex_flip}`)}${cropMarksSvg("var(--c-navy)")}</section>`);
  homePages.push(`<section class="page test">${svg(back, `ALIGNMENT TEST · BACK (page ${testFrontPage + 1}) · offset x ${hp.back_offset_x_mm} mm, y ${hp.back_offset_y_mm} mm`)}</section>`);
  // label_dy_mm: the slot labels sit this far below each cross centre, on both sides (each side is read upright).
  plan.alignment_test = { front_page: testFrontPage, back_page: testFrontPage + 1, label_dy_mm: 16 };
}

// Card sheets
sheets.forEach((s, si) => {
  const fronts = [], backsHtml = [], slots = [];
  for (let i = 0; i < perSheet; i++) {
    const col = i % hp.columns, row = Math.floor(i / hp.columns);
    const c = s.cards[i];
    const b = backSlot(col, row);
    const bp = slotXY(b.col, b.row);
    const { x, y } = slotXY(col, row);
    if (c) fronts.push(cardInSlot(renderFront(c, gateMap[c.gate]), x, y));
    if (c || hp.fill_all_back_slots) backsHtml.push(cardInSlot(renderBack(s.gate, backs), bp.x + hp.back_offset_x_mm, bp.y + hp.back_offset_y_mm));
    slots.push({
      slot: i + 1, front: c ? { id: c.id, card_type: c.card_type, gate: c.gate } : null, back_gate: c || hp.fill_all_back_slots ? s.gate : null,
      front_pos: { col, row }, back_pos: b,
      front_box_mm: { x: f2(x), y: f2(y), w: cellW, h: cellH },
      back_box_mm: { x: f2(bp.x + hp.back_offset_x_mm), y: f2(bp.y + hp.back_offset_y_mm), w: cellW, h: cellH },
    });
  }
  const ids = s.cards.map((c) => `${c.id}${c.card_type === "answer" ? "(A)" : ""}`);
  const pFront = firstCardPage + si * 2;
  homePages.push(`<section class="page">${fronts.join("")}${cropMarksSvg("var(--c-navy)")}${sideLabel(`SHEET ${si + 1}/${totalSheets} · GATE ${s.gate} · FRONT · page ${pFront} · ${ids[0]} – ${ids[ids.length - 1]}`)}</section>`);
  homePages.push(`<section class="page">${backsHtml.join("")}${sideLabel(`SHEET ${si + 1}/${totalSheets} · GATE ${s.gate} · BACK · page ${pFront + 1}`)}</section>`);
  plan.sheets.push({ sheet: si + 1, gate: s.gate, front_page: pFront, back_page: pFront + 1, slots });
});
plan.total_pages = homePages.length;
plan.first_card_page = firstCardPage;

const homeCss = `
  @page { size: ${hp.paper_width_mm}mm ${hp.paper_height_mm}mm; margin: 0; }
  html, body { margin: 0; padding: 0; background: var(--c-white); }
  .page { position: relative; width: ${hp.paper_width_mm}mm; height: ${hp.paper_height_mm}mm; overflow: hidden; break-after: page; page-break-after: always; }
  .page:last-child { break-after: auto; page-break-after: auto; }
  .slot { position: absolute; }
  .slot.clip { clip-path: inset(0); } /* exact vector clip; overflow:hidden is snapped to whole CSS px in Chrome PDFs */
  .overlay { position: absolute; inset: 0; width: 100%; height: 100%; }
  .side-label { position: absolute; top: 50%; transform: translate(-50%, -50%) rotate(-90deg); transform-origin: center; white-space: nowrap; font-family: var(--font-sign); font-weight: 600; font-size: 7pt; letter-spacing: .08em; color: var(--c-navy); }
  .t-trim { fill: none; stroke: var(--c-navy); stroke-width: .25; stroke-dasharray: 1.2 1; }
  .t-cross { fill: none; stroke: var(--c-navy); stroke-width: .3; }
  .t-cross.b { stroke: var(--c-teal-deep); stroke-width: .35; }
  .t-tick { stroke: var(--c-teal-deep); stroke-width: .2; }
  .t-tri { fill: var(--c-navy); }
  .t-lbl { font-family: var(--font-sign); font-weight: 700; font-size: 3.2px; letter-spacing: .1px; text-anchor: middle; fill: var(--c-navy); }
  .t-small { font-family: var(--font-text); font-size: 2.2px; text-anchor: middle; fill: var(--c-teal-deep); }
  .doc { box-sizing: border-box; padding: 16mm 18mm 14mm; font-family: var(--font-text); font-size: 9.6pt; line-height: 1.42; color: var(--c-navy); }
  .doc .tri { display: inline-block; width: .8em; height: .72em; vertical-align: 0; }
  .doc-band { display: flex; justify-content: space-between; font-family: var(--font-sign); font-weight: 700; letter-spacing: .12em; font-size: 8pt; border-bottom: .5mm solid var(--c-turquoise); padding-bottom: 2mm; margin-bottom: 6mm; }
  .doc h1 { font-family: var(--font-sign); font-weight: 800; font-size: 26pt; line-height: 1; margin: 0; }
  .doc .fr-sub { margin: 1mm 0 4mm; font-style: italic; color: var(--c-teal-deep); }
  .doc h2 { font-family: var(--font-sign); font-weight: 800; font-size: 13pt; margin: 5mm 0 1.5mm; }
  .doc h2 span { font-family: var(--font-text); font-weight: 400; font-style: italic; font-size: 9pt; color: var(--c-teal-deep); margin-left: 2mm; }
  .doc ul, .doc ol { margin: 0; padding-left: 5mm; }
  .doc li { margin: 0.8mm 0; }
  .doc p { margin: 1.5mm 0; }
  .doc code { font-family: var(--font-sign); font-weight: 600; font-size: 9.2pt; letter-spacing: .02em; background: var(--c-turquoise-tint); padding: 0 1mm; border-radius: 1mm; }
  .doc .foot { margin-top: 4mm; padding: 2.5mm 3mm; background: var(--c-yellow-tint); border-left: 1.2mm solid var(--c-yellow); }
  .doc table { width: 100%; border-collapse: collapse; font-size: 8.4pt; margin-top: 2mm; }
  .doc th, .doc td { text-align: left; padding: 1mm 1.6mm; border-bottom: .2mm solid var(--c-turquoise-tint); }
  .doc th { font-family: var(--font-sign); font-weight: 700; letter-spacing: .06em; background: var(--c-navy); color: var(--c-white); }
`;
writeOut("build/home_print.html", `${head({ title: "Home print A4", rel: "../", settings, extraCss: homeCss })}<body>${homePages.join("\n")}</body></html>`);
writeOut("build/layout-plan.json", JSON.stringify(plan, null, 2));

/* --------------------------------------------------------- Print-shop PDF */
const ps = settings.print_shop;
const pageW = G.cardW + 2 * ps.slug_mm, pageH = G.cardH + 2 * ps.slug_mm;
if (ps.crop_marks && ps.crop_mark_offset_mm < G.bleed) throw new Error("print_shop.crop_mark_offset_mm must be ≥ bleed so marks stay outside the artwork.");
if (!["front-back-interleaved", "fronts-then-backs"].includes(ps.page_order)) throw new Error(`Unknown print_shop.page_order "${ps.page_order}".`);
function shopMarks() {
  if (!ps.crop_marks) return "";
  const s = ps.slug_mm, b = G.bleed, off = ps.crop_mark_offset_mm, len = ps.crop_mark_length_mm;
  const tx = [s + b, s + b + G.trimW], ty = [s + b, s + b + G.trimH];
  const L = [];
  for (const x of tx) { L.push([x, s + b - off - len, x, s + b - off]); L.push([x, s + b + G.trimH + off, x, s + b + G.trimH + off + len]); }
  for (const y of ty) { L.push([s + b - off - len, y, s + b - off, y]); L.push([s + b + G.trimW + off, y, s + b + G.trimW + off + len, y]); }
  // Crop marks are printer's marks, not artwork: drawn in pure black for registration.
  return `<svg class="overlay" viewBox="0 0 ${f2(pageW)} ${f2(pageH)}" aria-hidden="true">${L.map(([a, bb, c, d]) => `<line x1="${f2(a)}" y1="${f2(bb)}" x2="${f2(c)}" y2="${f2(d)}" stroke="#000000" stroke-width="${ps.crop_mark_stroke_mm}"/>`).join("")}</svg>`;
}
const totalShop = cards.length * 2;
// Page sequence: each entry is one PDF page (a card side).
const shopSeq = ps.page_order === "fronts-then-backs"
  ? [...cards.map((c) => ({ c, side: "front" })), ...cards.map((c) => ({ c, side: "back" }))]
  : cards.flatMap((c) => [{ c, side: "front" }, { c, side: "back" }]);
const shopPlan = { page_order: ps.page_order, page_width_mm: f2(pageW), page_height_mm: f2(pageH), pages: [] };
const shopPages = shopSeq.map(({ c, side }, i) => {
  const page = i + 1;
  shopPlan.pages.push({ page, id: c.id, card_type: c.card_type, gate: c.gate, side });
  const sideTxt = side === "front" ? `FRONT (Gate ${c.gate})` : `BACK (Gate ${c.gate})`;
  const info = ps.slug_info_text ? `<div class="slug">${esc(`${c.id} · ${c.card_type.toUpperCase()} · ${sideTxt} · ${G.trimW}×${G.trimH} mm + ${G.bleed} mm bleed · p. ${page}/${totalShop}`)}</div>` : "";
  const art = side === "front" ? renderFront(c, gateMap[c.gate]) : renderBack(c.gate, backs);
  return `<section class="page"><div class="slot" style="left:${ps.slug_mm}mm;top:${ps.slug_mm}mm">${art}</div>${shopMarks()}${info}</section>`;
});
const shopCss = `
  @page { size: ${f2(pageW)}mm ${f2(pageH)}mm; margin: 0; }
  html, body { margin: 0; padding: 0; background: #FFFFFF; }
  .page { position: relative; width: ${f2(pageW)}mm; height: ${f2(pageH)}mm; overflow: hidden; break-after: page; page-break-after: always; }
  .page:last-child { break-after: auto; page-break-after: auto; }
  .slot { position: absolute; }
  .overlay { position: absolute; inset: 0; width: 100%; height: 100%; }
  .slug { position: absolute; left: 0; right: 0; bottom: ${f2(Math.max(0.8, ps.slug_mm / 2 - 2.6))}mm; text-align: center; font-family: var(--font-sign); font-weight: 600; font-size: 4.6pt; letter-spacing: .06em; color: #000000; }
`;
writeOut("build/print_shop.html", `${head({ title: "Print shop", rel: "../", settings, extraCss: shopCss })}<body>${shopPages.join("\n")}</body></html>`);
writeOut("build/print-shop-plan.json", JSON.stringify(shopPlan, null, 2));
writeOut("build/print-geometry.json", JSON.stringify({
  card: G, home: { cellW, cellH, marginX: f2(marginX), marginY: f2(marginY), blockW, blockH, sheets: totalSheets, pages: homePages.length },
  shop: { pageW: f2(pageW), pageH: f2(pageH), pages: shopPages.length, slug: ps.slug_mm, page_order: ps.page_order },
}, null, 2));

console.log(`✓ build/home_print.html — ${homePages.length} pages (${totalSheets} duplex card sheets, margins ${f2(marginX)} × ${f2(marginY)} mm)`);
console.log(`✓ build/print_shop.html — ${shopPages.length} pages (${f2(pageW)} × ${f2(pageH)} mm, ${ps.page_order})`);
console.log(`✓ data/cards.csv — ${cards.length} rows`);
